/**
 * OCR 변환 상태 체크 스토어
 *
 * 사용 흐름도:
 * 1. SupportOcr.vue 에서 변환 시작 → checkOcrStatus() 로 사용 가능 여부 확인
 * 2. 사용 가능시: resetStatus() + startPolling() 호출
 * 3. 3 초 간격으로 statusOcr API 호출 (폴링)
 * 4. status 가 'complete' 가 되면 폴링 중단 + 사용 횟수 초기화
 * 5. Header.vue 의 알림 아이콘에 'new' 배지 표시/제거
 * 6. 사용자가 알림 클릭 → markAsRead() 로 'new' 제거 (localStorage 에 저장)
 */

import { ref } from 'vue'
import { readUser } from '@/storage/userStorage.js'
import { inf } from '@/api/interface'
import { isSuccess } from '@/utils/common'

// localStorage 에 저장될 키 이름
const STORAGE_KEY = 'ocrStatusCheck'

// 최대 사용 횟수 조회 실패 시 사용할 기본값
export const DEFAULT_MAX_USE_OCR = 5

// 폴링 간격 하한 (0 이나 음수가 들어오면 setInterval 이 사실상 무한 루프가 된다)
const MIN_POLLING_INTERVAL = 1000
const DEFAULT_POLLING_INTERVAL = 3000

/**
 * 스토어 기본값
 * - hasNew: true 이면 알림 아이콘에 'new' 배지 표시
 * - lastChecked: 마지막 체크 시간
 * - useCount: 오늘 사용 횟수 (status 가 200 이 아닌 group_id 중복 카운트)
 * - isRead: 사용자가 알림을 확인했는지 여부 (true 면 완료라도 배지 안 표시)
 * - savedDate: useCount 를 저장한 날짜(YYYY-MM-DD). 날짜가 바뀌면 '오늘 사용 횟수' 는 무효
 * - completedItems: complete 된 항목 목록 (SupportOcrList 에서 업데이트용, 저장하지 않음)
 */
export const createDefaultStatus = () => ({
    hasNew: false,          // true: 변환 완료 대기 중 (알림 배지 표시)
    lastChecked: null,      // 마지막 상태 체크 타임스탬프
    useCount: 0,            // 오늘 사용 횟수
    isRead: true,           // 사용자가 알림 확인 여부
    savedDate: '',          // useCount 기준 날짜
    completedItems: []      // complete 된 항목 목록
})

const ocrStatusCheckStore = ref(createDefaultStatus())

// 폴링 타이머 ID
let pollingInterval = null

const safeParse = (raw) => {
    try {
        return raw ? JSON.parse(raw) : null
    } catch (e) {
        return null
    }
}

/**
 * 로컬 기준 오늘 날짜 키(YYYY-MM-DD)
 * @param {Date} now
 * @returns {string}
 */
export const todayKey = (now = new Date()) => {
    const d = now instanceof Date && !Number.isNaN(now.getTime()) ? now : new Date()
    const mm = String(d.getMonth() + 1).padStart(2, '0')
    const dd = String(d.getDate()).padStart(2, '0')
    return `${d.getFullYear()}-${mm}-${dd}`
}

/**
 * 0 이상의 정수로 변환. 변환 불가하면 fallback
 * @param {*} value
 * @param {number} fallback
 * @returns {number}
 */
export const toCount = (value, fallback = 0) => {
    if (value === null || value === undefined || value === '') return fallback
    if (typeof value === 'object' || typeof value === 'boolean') return fallback
    const n = Number(value)
    if (!Number.isFinite(n) || n < 0) return fallback
    return Math.floor(n)
}

/**
 * localStorage 에서 읽은 값을 스토어 형태로 정규화
 * - 저장된 날짜가 오늘이 아니면 '오늘 사용 횟수' 를 신뢰할 수 없으므로 0 으로 되돌린다.
 *   (그러지 않으면 어제 5 회 쓴 사용자가 오늘 첫 변환에서 사용 횟수 초과로 막힌다)
 * @param {*} raw - JSON.parse 결과
 * @param {string} today - 오늘 날짜 키
 * @returns {Object}
 */
export const normalizeStoredStatus = (raw, today = todayKey()) => {
    const base = createDefaultStatus()
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return base

    const savedDate = typeof raw.savedDate === 'string' ? raw.savedDate : ''
    const isToday = savedDate !== '' && savedDate === today

    return {
        ...base,
        hasNew: raw.hasNew === undefined || raw.hasNew === null ? false : !!raw.hasNew,
        lastChecked: typeof raw.lastChecked === 'number' ? raw.lastChecked : null,
        useCount: isToday ? toCount(raw.useCount, 0) : 0,
        isRead: raw.isRead === undefined || raw.isRead === null ? true : !!raw.isRead,
        savedDate: isToday ? savedDate : ''
    }
}

/**
 * localStorage 에서 상태 로드
 * 앱 시작 시 또는 컴포넌트 마운트 시 호출
 */
export const loadStatus = () => {
    try {
        const stored = localStorage.getItem(STORAGE_KEY)
        if (!stored) return

        const next = normalizeStoredStatus(safeParse(stored))
        // completedItems 는 저장하지 않는 휘발 상태다. 통째로 갈아끼우면
        // SupportOcrList/SupportOcrListCurrent 가 보고 있는 목록이 undefined 가 되므로 유지한다.
        const prev = ocrStatusCheckStore.value
        next.completedItems = Array.isArray(prev?.completedItems) ? prev.completedItems : []
        ocrStatusCheckStore.value = next
    } catch (e) {
        console.error('Failed to load OCR status from storage:', e)
    }
}

/**
 * 상태를 localStorage 에 저장
 * hasNew 또는 lastChecked 가 변경될 때마다 호출
 */
const saveStatus = () => {
    try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify({
            hasNew: ocrStatusCheckStore.value.hasNew,
            lastChecked: ocrStatusCheckStore.value.lastChecked,
            useCount: ocrStatusCheckStore.value.useCount,
            isRead: ocrStatusCheckStore.value.isRead,
            savedDate: todayKey()
        }))
        ocrStatusCheckStore.value.savedDate = todayKey()
    } catch (e) {
        console.error('Failed to save OCR status to storage:', e)
    }
}

// status 가 200 이면 변환이 끝난(추가 사용으로 세지 않는) 항목
const isDoneItem = (item) => String(item?.status ?? '') === '200'

/**
 * todayOcrList 에서 사용 횟수 계산
 * - group_id 를 중복으로 묶음
 * - status 가 200 이 아닌 경우만 카운트 (1 회 호출한 것으로 간주)
 * @param {Array} todayOcrList - API 에서 받은 오늘 OCR 리스트
 * @returns {number} 사용 횟수
 */
export const calculateUseCount = (todayOcrList) => {
    if (!Array.isArray(todayOcrList)) return 0

    // group_id 로 중복 제거
    const groupMap = new Map()

    todayOcrList.forEach((item, idx) => {
        if (!item || typeof item !== 'object') return

        const groupId = item.group_id
        // group_id 가 없는 항목끼리는 서로 다른 요청이므로 하나로 묶지 않는다
        const key = groupId === null || groupId === undefined || groupId === ''
            ? `__no_group_${idx}__`
            : String(groupId)

        if (!groupMap.has(key)) {
            // 처음 등장하는 group_id
            groupMap.set(key, item)
            return
        }

        // 이미 존재하는 group_id: status 가 200 이 아닌 경우로 업데이트
        if (isDoneItem(groupMap.get(key)) && !isDoneItem(item)) {
            groupMap.set(key, item)
        }
    })

    // status 가 200 이 아닌 개수 카운트
    let count = 0
    for (const item of groupMap.values()) {
        if (!isDoneItem(item)) count++
    }

    return count
}

/**
 * todayOcrList 에서 변환이 진행 완료된(대기 '0' 이 아닌) 항목만 추출
 * @param {Array} todayOcrList
 * @returns {Array}
 */
export const extractCompletedItems = (todayOcrList) => {
    if (!Array.isArray(todayOcrList)) return []
    return todayOcrList.filter((item) => item && String(item.status ?? '') !== '0')
}

/**
 * OCR 변환 상태 확인 (API 호출)
 * - status 가 'complete' 면 폴링 중단 + 사용 횟수 초기화
 * - todayOcrList 를 받아 사용 횟수 계산
 * - isRead 가 true 면 이미 확인한 상태이므로 hasNew 를 true 로 안 설정
 * @returns {Promise<boolean>} status 가 'complete' 이면 true, 아니면 false
 */
export const checkOcrStatus = async () => {
    const userId = String(readUser()?.user_id || '')
    if (!userId) return false
    try {
        const res = await inf.tools.statusOcr.call({ user_id: userId })

        if (!isSuccess(res)) {
            stopPolling()  // 폴링 중단
            return false
        }

        const body = res?.data?.body
        const todayOcrList = Array.isArray(body?.todayOcrList) ? body.todayOcrList : []

        // 대기('0') 가 아닌 항목들을 목록 갱신용으로 전달
        ocrStatusCheckStore.value.completedItems = extractCompletedItems(todayOcrList)

        // status 가 'complete' 면 변환 완료 → 사용 횟수 초기화
        if (body?.status === 'complete') {
            ocrStatusCheckStore.value.useCount = 0  // 사용 횟수 초기화

            // complete 가 되면 hasNew = true (SupportOcrList 에서 목록 새로고침)
            if (!ocrStatusCheckStore.value.isRead) {
                ocrStatusCheckStore.value.hasNew = true
            }

            ocrStatusCheckStore.value.lastChecked = Date.now()
            saveStatus()
            stopPolling()  // 폴링 중단
            return true
        }

        // 목록이 비어 있으면 사용 횟수도 0 이다. 예전에는 비어 있을 때 갱신을 건너뛰어
        // 어제 저장된 useCount 가 그대로 남아 오늘 변환이 막혔다.
        ocrStatusCheckStore.value.useCount = calculateUseCount(todayOcrList)
        saveStatus()

        return false
    } catch (e) {
        console.error('Failed to check OCR status:', e)
        return false
    }
}

/**
 * OCR 상태 폴링 시작
 * @param {number} interval - 폴링 간격 (밀리초, 기본값: 3000ms)
 */
const startPolling = (interval = DEFAULT_POLLING_INTERVAL) => {
    if (pollingInterval) return  // 이미 폴링 중이면 중복 시작 방지
    loadStatus()
    // hasNew 이 false 면 폴링 시작 (변환 대기 중)
    // hasNew 이 true 면 이미 complete 상태이므로 폴링 불필요
    if (!ocrStatusCheckStore.value.hasNew) {
        const delay = Math.max(MIN_POLLING_INTERVAL, toCount(interval, DEFAULT_POLLING_INTERVAL))
        pollingInterval = setInterval(() => {
            checkOcrStatus()
        }, delay)
    }
}

/**
 * OCR 상태 폴링 중단
 * 변환 완료 시 또는 컴포넌트 언마운트 시 호출
 */
const stopPolling = () => {
    if (pollingInterval) {
        clearInterval(pollingInterval)
        pollingInterval = null
    }
}

/**
 * 알림을 읽음 처리
 * 사용자가 알림 아이콘을 클릭했을 때 호출 → 'new' 배지 제거
 * isRead = true 로 설정하여 새로고침해도 배지 안 표시
 */
const markAsRead = () => {
    ocrStatusCheckStore.value.hasNew = false
    ocrStatusCheckStore.value.isRead = true
    ocrStatusCheckStore.value.lastChecked = Date.now()
    saveStatus()
}

/**
 * OCR 변환 시작 시 상태 초기화
 * hasNew = false 로 설정하여 폴링 시작 (변환 대기 중)
 * isRead = false 로 초기화하여 새로운 변환으로 인식
 * complete 가 되면 checkOcrStatus 에서 hasNew = true 로 설정 (배지 표시)
 */
const resetStatus = () => {
    ocrStatusCheckStore.value.hasNew = false
    ocrStatusCheckStore.value.isRead = false
    ocrStatusCheckStore.value.lastChecked = Date.now()
    saveStatus()
}

/**
 * OCR 변환 가능 여부 확인
 * @returns {Promise<{canUse: boolean, useCount: number, maxUse: number}>}
 */
export const canUseOcr = async () => {
    const userId = String(readUser()?.user_id || '')
    // 로그인 정보가 없으면 어차피 사용할 수 없으므로 최대 횟수 API 는 호출하지 않는다
    if (!userId) return { canUse: false, useCount: 0, maxUse: DEFAULT_MAX_USE_OCR }

    const maxCnt = await getMaxUseOcr()

    // 현재 사용 횟수가 최대 사용 횟수 미만이면 사용 가능
    const currentCount = ocrStatusCheckStore.value.useCount
    const canUse = currentCount < maxCnt

    return {
        canUse,
        useCount: currentCount,
        maxUse: maxCnt
    }
}

/**
 * 사용 횟수 조회
 * @returns {number} 현재 사용 횟수
 */
export const getUseCount = () => {
    return ocrStatusCheckStore.value.useCount
}

/**
 * 최대 사용 횟수 조회
 * - 숫자가 아닌 응답(null, 객체, 문자열 등)이 오면 기본값으로 폴백한다.
 *   NaN 이 그대로 쓰이면 `useCount < NaN` 이 항상 false 라 OCR 이 영구히 막힌다.
 * @returns {Promise<number>} 최대 사용 횟수
 */
export const getMaxUseOcr = async () => {
    try {
        const res = await inf.tools.ocrCnt.call()
        return toCount(res?.data?.body, DEFAULT_MAX_USE_OCR)
    } catch (error) {
        return DEFAULT_MAX_USE_OCR
    }
}

export {
    ocrStatusCheckStore,   // Header.vue 에서 알림 아이콘 상태 표시용
    startPolling,          // SupportOcr.vue 에서 변환 시작 후 호출
    stopPolling,           // 상태 체크 완료 시 호출
    markAsRead,            // Header.vue 에서 알림 클릭 시 호출
    resetStatus,           // SupportOcr.vue 에서 변환 시작 전 호출
}
	}
}

/** 개별 삭제 */
const removeFile = (idx) => {
	const item = fileList.value[idx]
	if (!item) return

	fileList.value.splice(idx, 1)

	const apiIdx = fileList.value.findIndex(
		(f) => `${f.name}` === item.name,
	)
	if (apiIdx > -1) fileList.value.splice(apiIdx, 1)
}

/** 멀티파트 전송용 */
const buildMultipartFormData = (extra = {}) => {
	const fd = new FormData()
	fileList.value.forEach((file) => fd.append('document', file))
	Object.entries(extra).forEach(([k, v]) => {
		if (v === undefined || v === null) return
		fd.append(k, String(v))
	})
	return fd
}

onBeforeUnmount(() => {
  	fileList.value.forEach((i) => i.previewUrl && URL.revokeObjectURL(i.previewUrl))
})

const startConversion = async () => {
	const formData = buildMultipartFormData({ user_id:  userId})
	if(formData.getAll('document').length == 0){
		openAlert('파일을 업로드 해주세요.')
		return
	}
	try{
		startLoading()
		const res = await inf.tools.sttParse.call(formData);
		if(!isSuccess(res)){
			openAlert('업로드 실패하였습니다.\n재시도 해주세요.')
            return;
		}
		const data = res.data?.data ?? {id : "17"}
		router.push({
            path: '/support/stt/detail',
            query: {selectId : data.id}
        });

	}catch(e){
		if(e == 'COM') return
		openAlert('업로드 실패하였습니다.\n재시도 해주세요.')
	} finally {
		stopLoading()
	}
}

const gotoList = () => router.push({ path: '/support/stt/list' })
watch(fileList, ()=>{}, {deep: true})
onMounted(async ()=>{
	const data = await getAppInfo({mode:'stt'})
  	subTitle.value = data.description ?? '음성을 텍스트로 변환시켜드려요.'
	modeCheckCount({ mode: 'stt' })
})	
</script>

